from pathlib import Path
import json
root=Path('outputs/orin-desk-agent/evidence/56-yolo26')
models=[('rtmdet-rtmpose-baseline','当前 RTMDet + RTMPose'),('yolo26s-pose-engine','YOLO26s-Pose'),('yolo26m-pose-engine','YOLO26m-Pose')]
data={}
for model,title in models:
 data[model]={'title':title,'benchmark':json.loads((root/model/'benchmark.json').read_text()),'quality':json.loads((root/model/'quality.json').read_text())}
html='''<!doctype html><meta charset="utf-8"><title>Orin 姿态模型照片对照</title><style>
*{box-sizing:border-box}body{margin:0;background:#f4f5f0;color:#253c35;font:15px/1.65 system-ui,-apple-system,"PingFang SC",sans-serif}main{max-width:1640px;margin:auto;padding:32px}h1{font-size:30px;margin:0}p{color:#6c7b73;margin:8px 0 22px}button{border:1px solid #ced9cf;border-radius:9px;padding:8px 20px;background:#fff;color:#253c35;margin-right:8px;cursor:pointer}button.active{background:#28634c;color:white}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.cell{background:white;border:1px solid #e1e7dc;border-radius:12px;overflow:hidden}.cell img{width:100%;display:block}.caption{padding:12px 16px}h2{font-size:19px;margin:28px 0 12px}.sub{color:#66766d;font-size:13px}.metrics{display:flex;gap:25px;margin:18px 0}.metric{background:#e5eddd;padding:16px 22px;border-radius:12px}.note{background:#fff;border-left:3px solid #97af84;padding:16px;margin-top:20px}strong{font-weight:600}@media(max-width:750px){.grid{grid-template-columns:1fr}.metrics{flex-direction:column}}
</style><main><h1>同一张照片，三个视觉方案</h1><p>AGX Orin 64GB · 30W · TensorRT FP16 · 当前服务持续运行 · 未替换线上模型</p><div id="controls"><button class="active" data-view="full">完整画面</button><button data-view="workstation">当前工位裁剪</button></div><div class="metrics" id="metrics"></div><div class="note">黄色点和线仅显示置信度 ≥0.55 的关节。不同模型的分数未校准，点数更多不等于关节点更准确。下方“坐站”是套用现有几何规则的结果；未检出人并不等于确认离开。</div><div id="cases"></div><p>4 张独立图片，没有逐关节点人工真值；这次测试不能证明连续坐站统计误差或切换延迟达标。每个模型计时 200 次，含预处理、推理、后处理及结果转 CPU，不含磁盘读图和 Cosmos。</p></main><script>const data=DATA;const cases=[['standing','明显站姿','可见上半身，腿部受遮挡'],['sitting','明显坐姿','椅背挡住部分身体'],['occluded','椅背遮挡：用户确认仍坐着','重点：未检出人不是无人'],['empty','空工位：用户确认离开','此图来自看板截图裁剪，含文字覆盖']];function render(view){document.getElementById('metrics').innerHTML=Object.values(data).map(d=>`<div class="metric"><strong>${d.title}</strong><div>P50 ${d.benchmark.by_view[view].p50_ms.toFixed(1)} ms · P95 ${d.benchmark.by_view[view].p95_ms.toFixed(1)} ms</div></div>`).join('');document.getElementById('cases').innerHTML=cases.map(([id,title,desc])=>`<section id="${id}"><h2>${title} <span class="sub">${desc}</span></h2><div class="grid">${Object.entries(data).map(([model,d])=>{const r=d.quality.find(r=>r.case===id&&r.view===view);return `<div class="cell"><div class="caption"><strong>${d.title}</strong></div><img src="${model}/${id}-${view}.jpg"><div class="caption">${r.detections.length?'检出人体':'未检出人体'} · ${r.visible_keypoints} 个高置信关节<div class="sub">坐站：${r.posture==='unknown'?'证据不足':r.posture==='away'?'未检出人，不能判定坐站':r.posture}</div></div></div>`}).join('')}</div></section>`).join('')}document.querySelectorAll('button').forEach(b=>b.onclick=()=>{document.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));render(b.dataset.view)});render('full');</script>'''.replace('DATA',json.dumps(data,ensure_ascii=False))
(root/'照片对照.html').write_text(html)
print('Written comparison HTML')
